/* REAL WEATHER: GPS + live Open-Meteo data */
async function loadRealWeather(lat,lon){
  const set=(id,v)=>{const e=$(id);if(e)e.textContent=v;};
  const statusEl=$("locationStatus");
  try{
    const url=`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,precipitation,weather_code,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max&forecast_days=7&timezone=auto`;
    const r=await fetch(url,{cache:'no-store'});
    if(!r.ok)throw new Error('Weather request failed');
    const w=await r.json();
    const temp=Math.round(w.current?.temperature_2m??0);
    const humidity=Math.round(w.current?.relative_humidity_2m??0);
    const rain=Math.round(w.daily?.precipitation_probability_max?.[0]??0);
    const wind=Math.round(w.current?.wind_speed_10m??0);
    set("temperature",temp);set("todayTemp",temp);set("humidity",humidity+"%");
    set("rainChance",rain+"%");set("todayRainBadge","RAIN "+rain+"%");
    const items=document.querySelectorAll('#weather .weather-item');
    if(items[2])items[2].innerHTML=`ðŸŒ¬ï¸ Wind<br><b>${wind} km/h</b>`;

    const code=w.current?.weather_code;
    const desc={0:"Clear Sky â˜€ï¸",1:"Mainly Clear ðŸŒ¤ï¸",2:"Partly Cloudy â›…",3:"Overcast â˜ï¸",45:"Fog ðŸŒ«ï¸",48:"Fog ðŸŒ«ï¸",51:"Light Drizzle ðŸŒ¦ï¸",53:"Drizzle ðŸŒ¦ï¸",55:"Heavy Drizzle ðŸŒ§ï¸",61:"Light Rain ðŸŒ¦ï¸",63:"Rain ðŸŒ§ï¸",65:"Heavy Rain ðŸŒ§ï¸",71:"Light Snow ðŸŒ¨ï¸",73:"Snow ðŸŒ¨ï¸",75:"Heavy Snow â„ï¸",80:"Rain Showers ðŸŒ¦ï¸",81:"Rain Showers ðŸŒ§ï¸",82:"Heavy Rain Showers â›ˆï¸",95:"Thunderstorm â›ˆï¸",96:"Thunderstorm + Hail â›ˆï¸",99:"Thunderstorm + Hail â›ˆï¸"};
    const weatherText=document.querySelector('#weather .weather-main > div:nth-of-type(3)');
    if(weatherText)weatherText.textContent=desc[code]||"Current conditions";

    const disease=Math.max(5,Math.min(95,Math.round(humidity*.55+rain*.35+(temp>=20&&temp<=32?10:0))));
    set("diseaseRisk",disease+"%");
    const badge=$("diseaseBadge");
    if(badge){
      const level=disease>=70?"HIGH":disease>=40?"MODERATE":"LOW";
      badge.textContent=level;
      badge.className="badge "+(level==="HIGH"?"red":level==="MODERATE"?"yellow":"green");
    }

    const box=document.getElementById('forecastDays')||document.querySelector('#weather .forecast');
    if(box&&w.daily){
      box.innerHTML='';
      const names=['SUN','MON','TUE','WED','THU','FRI','SAT'];
      (w.daily.time||[]).slice(0,7).forEach((day,i)=>{
        const d=new Date(day+"T12:00:00");
        const el=document.createElement('div');el.className='forecast-day';
        el.innerHTML=`<b>${names[d.getDay()]}</b><br>${Math.round(w.daily.temperature_2m_max?.[i]??0)}Â° / ${Math.round(w.daily.temperature_2m_min?.[i]??0)}Â°<br><small>${Math.round(w.daily.precipitation_probability_max?.[i]??0)}%</small>`;
        box.appendChild(el);
      });
    }
    if(statusEl)statusEl.textContent='Live weather updated for your current location.';
  }catch(e){
    console.warn('AgriShield weather:',e);
    if(statusEl)statusEl.textContent='Location detected, but live weather is unavailable.';
  }
}
function requestRealLocation(){
  const loc=$("weatherLocation");if(!loc)return;
  let statusEl=$("locationStatus");
  if(!statusEl){
    statusEl=document.createElement('small');statusEl.id='locationStatus';
    statusEl.style.cssText='display:block;margin-top:4px;opacity:.9';
    loc.parentNode.appendChild(statusEl);
  }
  if(!navigator.geolocation){
    statusEl.textContent='Geolocation is not supported by this browser.';return;
  }
  statusEl.textContent='Requesting your current locationâ€¦';
  navigator.geolocation.getCurrentPosition(pos=>{
    const lat=pos.coords.latitude,lon=pos.coords.longitude;
    window.__agrishieldLocation={latitude:lat,longitude:lon};
    loc.textContent=`${lat.toFixed(5)}, ${lon.toFixed(5)}`;
    const langCode=(typeof language==='string'&&language)?language:'en';
    fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lon}&zoom=10&addressdetails=1`,{headers:{'Accept-Language':langCode}})
      .then(r=>r.ok?r.json():Promise.reject(new Error('Reverse geocode failed')))
      .then(d=>{
        const a=d.address||{},place=a.city||a.town||a.village||a.municipality||a.county||a.state;
        if(place)loc.textContent=place+(a.state&&a.state!==place?', '+a.state:'');
      }).catch(()=>{}).finally(()=>loadRealWeather(lat,lon));
  },err=>{
    console.warn('Geolocation:',err);
    statusEl.textContent=err.code===1?'Location permission was denied. Allow Location and press Refresh again.':'Unable to detect location. Press Refresh to try again.';
  },{enableHighAccuracy:true,timeout:20000,maximumAge:60000});
}
$("refreshWeather").onclick=requestRealLocation;
requestRealLocation();

