function translateWholePage(lang){
 const t=EXTRA_T[lang]||{};
 document.querySelectorAll('body *:not(script):not(style)').forEach(el=>{
  if(el.children.length!==0)return;
  const id=el.id||'';
  if(['resultCrop','resultDetection','resultConfidence','resultSeverity','resultSymptoms','resultRecommendation','weatherLocation','temperature','todayTemp','humidity','rainChance','diseaseRisk','homeDiseaseRisk','homePestRisk','todayRainBadge','imageName','scanCount'].includes(id))return;
  if(!el.dataset.baseText)el.dataset.baseText=el.textContent.trim();
  const base=el.dataset.baseText;
  if(lang==='en')el.textContent=base;
  else if(t[base])el.textContent=t[base];
 });
}
const oldApplyLanguage=applyLanguage;
applyLanguage=function(lang){oldApplyLanguage(lang);translateWholePage(lang);if(typeof renderPests==='function')renderPests();if(typeof renderAdvisory==='function')renderAdvisory();if(typeof updateForecast==='function')updateForecast();};

/* ---------- BACK ARROW: robust navigation ---------- */
const originalGoBack=goBack;
goBack=function(){
 if(pageHistory.length>1){pageHistory.pop();showSection(pageHistory[pageHistory.length-1],false);}else{showSection('home',false);}
 window.scrollTo({top:0,behavior:'smooth'});
};
document.addEventListener('click',e=>{const b=e.target.closest('.back-btn,[data-back]');if(b){e.preventDefault();e.stopImmediatePropagation();goBack();}},true);

/* ---------- CAMERA: one direct camera option ---------- */
let liveStream=null;
function buildCameraModal(){
 if(document.getElementById('liveCamera'))return;
 const m=document.createElement('div');m.id='liveCamera';m.className='modal';m.innerHTML='<div class="modal-box"><div class="modal-header"><h2>ðŸ“· Camera</h2><button class="close-modal" id="closeLiveCamera">Ã—</button></div><video id="liveVideo" autoplay playsinline></video><br><button class="btn full" id="captureLive">ðŸ“¸ Capture Photo</button></div>';
 document.body.appendChild(m);
 document.getElementById('closeLiveCamera').onclick=closeLiveCamera;
 document.getElementById('captureLive').onclick=()=>{
  const v=document.getElementById('liveVideo');if(!v.videoWidth)return;
  const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);
  c.toBlob(blob=>{const f=new File([blob],'crop-camera-photo.jpg',{type:'image/jpeg'});handleImage(f);closeLiveCamera();},'image/jpeg',.92);
 };
}
function closeLiveCamera(){const m=document.getElementById('liveCamera');if(m)m.classList.remove('show');if(liveStream){liveStream.getTracks().forEach(t=>t.stop());liveStream=null;}}
async function openDirectCamera(){
 buildCameraModal();
 try{
  if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia)throw new Error('no camera api');
  liveStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});
  document.getElementById('liveVideo').srcObject=liveStream;document.getElementById('liveCamera').classList.add('show');
 }catch(e){
  /* Mobile/browser fallback: capture=environment requests the phone camera. */
  const input=document.getElementById('cameraInput');input.setAttribute('capture','environment');input.click();
 }
}
const takeBtn=document.getElementById('takePhotoBtn')||document.querySelector('.camera-option.take');
if(takeBtn){takeBtn.onclick=e=>{e.preventDefault();openDirectCamera();};}

/* ---------- REAL USER PEST REPORTS ONLY ---------- */
function getRealPests(){return JSON.parse(localStorage.getItem('agrishieldPestReports')||'[]');}
function saveRealPests(x){localStorage.setItem('agrishieldPestReports',JSON.stringify(x));}
function renderPests(){
 let box=document.getElementById('recentPestReports'),cards=document.getElementById('pestCards');if(!cards)return;if(!box){const card=[...document.querySelectorAll('#pest .card')].find(c=>/Recent Reports/.test(c.textContent));if(card){box=document.createElement('div');box.id='recentPestReports';card.appendChild(box);}}if(!box)return;
 const reports=getRealPests();box.innerHTML='';cards.innerHTML='';
 if(!reports.length){box.innerHTML='<div class="empty" style="padding:25px 10px"><div style="font-size:42px">ðŸ›</div><h3>No pest reports yet</h3><p>Add an observation below to create your first real report.</p></div>';return;}
 reports.slice().sort((a,b)=>b.id-a.id).forEach(r=>{
  const cls=r.severity==='High'?'high':r.severity==='Moderate'?'medium':'low',badge=r.severity==='High'?'red':r.severity==='Moderate'?'yellow':'green',pct=r.severity==='High'?85:r.severity==='Moderate'?55:25;
  const el=document.createElement('div');el.className='alert '+cls;el.innerHTML=`<b>${r.date}</b><div><b>${r.name}</b><br><span class="badge ${badge}">${r.severity.toUpperCase()}</span></div>`;box.appendChild(el);
  const c=document.createElement('div');c.className='card pest-card';c.innerHTML=`<div class="icon">ðŸ›</div><h3>${r.name}</h3><span class="badge ${badge}">${r.severity.toUpperCase()}</span><p>Added on ${r.date}.</p><div class="progress"><div style="width:${pct}%"></div></div><button class="btn secondary remove-pest" data-id="${r.id}">Remove</button>`;cards.appendChild(c);
 });
}
const oldAddPest=document.getElementById('addPest');
if(oldAddPest)oldAddPest.onclick=()=>{const name=document.getElementById('pestName').value,severity=document.getElementById('pestSeverity').value,r=getRealPests();r.push({id:Date.now(),name,severity,date:new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})});saveRealPests(r);renderPests();toast(name+' observation added ðŸ›');};
document.addEventListener('click',e=>{const b=e.target.closest('.remove-pest');if(b){saveRealPests(getRealPests().filter(x=>x.id!==Number(b.dataset.id)));renderPests();toast('Pest observation removed');}});

/* ---------- 7-DAY FORECAST: always includes Sat + Sun ---------- */
function updateForecast(){
 const box=document.getElementById('forecastDays')||document.querySelector('#weather .forecast');if(!box)return;box.innerHTML='';const names=['SUN','MON','TUE','WED','THU','FRI','SAT'],now=new Date();
 for(let i=0;i<7;i++){const d=new Date(now);d.setDate(now.getDate()+i);const temp=Math.round(25+Math.random()*7),rain=Math.round(15+Math.random()*65);const el=document.createElement('div');el.className='forecast-day';el.innerHTML=`<b>${names[d.getDay()]}</b><br>${temp}Â°<br><small>${rain}%</small>`;box.appendChild(el);}
}
updateForecast();

