     if(!crop){try{const c=await classifyCrop(src);crop=c.crop;cropScore=c.score}catch(e){console.warn('Crop classifier failed',e)}}
     let disease=namedDisease,confidence='â€”',severity='LOW',symptoms='The image is ready for review.',recommendation='Use the crop-specific guidance and confirm the diagnosis before treatment.';
