 /* Reliable speech synthesis with voice selection, resume and chunking. */
 function speak(){
   const r=window.latestScan;if(!r){toast(locale()==='te'?'à°®à±à°‚à°¦à±à°—à°¾ à°¸à±à°•à°¾à°¨à± à°šà±‡à°¯à°‚à°¡à°¿.':locale()==='hi'?'à¤ªà¤¹à¤²à¥‡ à¤¸à¥à¤•à¥ˆà¤¨ à¤•à¤°à¥‡à¤‚.':'Scan a crop first.');return}
   if(!('speechSynthesis'in window)){toast(locale()==='te'?'à°ˆ à°ªà°°à°¿à°•à°°à°‚à°²à±‹ à°µà°¾à°¯à°¿à°¸à± à°…à°‚à°¦à±à°¬à°¾à°Ÿà±à°²à±‹ à°²à±‡à°¦à±.':locale()==='hi'?'à¤‡à¤¸ à¤¡à¤¿à¤µà¤¾à¤‡à¤¸ à¤®à¥‡à¤‚ à¤†à¤µà¤¾à¤œà¤¼ à¤‰à¤ªà¤²à¤¬à¥à¤§ à¤¨à¤¹à¥€à¤‚ à¤¹à¥ˆ.':'Voice is not supported on this device.');return}
   const l=locale(),lab=l==='te'?['à°ªà°‚à°Ÿ: ',' à°¸à°®à°¸à±à°¯: ',' à°²à°•à±à°·à°£à°¾à°²à±: ',' à°¸à±‚à°šà°¨: ']:l==='hi'?['à¤«à¤¸à¤²: ',' à¤¸à¤®à¤¸à¥à¤¯à¤¾: ',' à¤²à¤•à¥à¤·à¤£: ',' à¤¸à¤²à¤¾à¤¹: ']:['Crop: ',' Problem: ',' Symptoms: ',' Recommendation: '];
   const txt=lab[0]+tr(r.crop,l)+lab[1]+tr(r.detection,l)+lab[2]+tr(r.symptoms,l)+lab[3]+tr(r.recommendation,l);
   const ss=speechSynthesis;ss.cancel();ss.resume();const voices=ss.getVoices();const pref=l==='te'?['te-IN','te']:l==='hi'?['hi-IN','hi']:['en-IN','en-US','en-GB','en'];const v=voices.find(x=>pref.some(p=>(x.lang||'').toLowerCase()===p.toLowerCase()))||voices.find(x=>pref.some(p=>(x.lang||'').toLowerCase().startsWith(p.split('-')[0])))||voices.find(x=>/en/i.test(x.lang||''))||voices[0];
   const parts=txt.match(/.{1,180}(?:\s|$)/g)||[txt];let i=0;document.querySelectorAll('.voice-floating').forEach(x=>x.classList.add('listening'));
   const next=()=>{if(i>=parts.length){document.querySelectorAll('.voice-floating').forEach(x=>x.classList.remove('listening'));return}const u=new SpeechSynthesisUtterance(parts[i++]);u.lang=v?.lang||(l==='te'?'te-IN':l==='hi'?'hi-IN':'en-IN');if(v)u.voice=v;u.rate=.84;u.volume=1;u.onend=next;u.onerror=()=>{document.querySelectorAll('.voice-floating').forEach(x=>x.classList.remove('listening'));toast(l==='te'?'à°µà°¾à°¯à°¿à°¸à± à°®à°³à±à°²à±€ à°¨à±Šà°•à±à°•à°‚à°¡à°¿.':l==='hi'?'à¤µà¥‰à¤‡à¤¸ à¤«à¤¿à¤° à¤¸à¥‡ à¤¦à¤¬à¤¾à¤à¤‚.':'Tap Listen again.')} ;ss.speak(u)};setTimeout(next,100)
 }
 function stop(){if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.resume()}document.querySelectorAll('.voice-floating').forEach(x=>x.classList.remove('listening'))}
 window.agrSpeakScan=speak;window.agrStopVoice=stop;
 const result=$('scanResult');if(result){const old=result.querySelector('.voice-assistant');if(old)old.remove();const d=document.createElement('div');d.className='voice-assistant';d.innerHTML='<button type="button" class="voice-btn" id="agrListenScan">ðŸ”Š Listen</button><button type="button" class="voice-btn stop" id="agrStopScan">â¹ Stop</button><span class="voice-help">Press Listen to hear the crop, problem, symptoms and advice.</span>';result.appendChild(d);$('agrListenScan').onclick=speak;$('agrStopScan').onclick=stop}
 if('speechSynthesis'in window)speechSynthesis.onvoiceschanged=()=>{};
